INSERT INTO `products` VALUES (1,1,1,1,'variable','V-neck Linen Blend Summer Dress','v-neck-linen-blend-summer-dress','MOD-W-001',NULL,NULL,89.00,69.00,5.00,45,10,5,'in_stock','Lightweight, breathable linen blend dress tailored for warm weather elegance.','Designed with relaxed sophistication, this dress features an airy silhouette, a feminine V-neckline, and sustainable organic linen fabric. Machine washable with minimal shrinkage.','[{\"key\":\"Pack of\",\"value\":\"1\"},{\"key\":\"Fabric\",\"value\":\"Cotton Blend\"},{\"key\":\"Sleeve\",\"value\":\"Full Sleeve\"},{\"key\":\"Pattern\",\"value\":\"Solid\"},{\"key\":\"Collar\",\"value\":\"Spread\"},{\"key\":\"Color\",\"value\":\"Grey\"}]','products/womens/women-1.jpg','[\"products/womens/women-2.jpg\",\"products/womens/women-3.jpg\"]',1,1,1,1,4.90,18,'published','2026-09-07 12:38:10','2026-09-12 20:11:25'),(1,2,1,1,'simple','Belted Relaxed Trench Coat','belted-relaxed-trench-coat','MOD-W-002',NULL,NULL,175.00,149.00,5.00,28,5,5,'in_stock','Timeless water-resistant double-breasted trench coat with removable waist belt.','Classic British outerwear styling re-imagined. Features premium weatherproof cotton gabardine, tortoise shell buttons, storm flaps, and spacious slant pockets.',NULL,'products/womens/women-4.jpg','[\"products/womens/women-5.jpg\",\"products/womens/women-6.jpg\"]',1,1,0,1,4.85,24,'published','2026-09-07 12:38:10','2026-09-07 13:04:49'),(1,3,1,3,'simple','Oversized Silk Knit Cardigan','oversized-silk-knit-cardigan','MOD-W-003',NULL,NULL,110.00,NULL,5.00,30,5,5,'in_stock','Ultra-soft cozy drape cardigan made from fine spun silk-wool blend.','The perfect layering essential for any season. Dropped shoulders, ribbed cuffs, and an open front silhouette that complements both casual denim and evening wear.',NULL,'products/womens/women-7.jpg','[\"products/womens/women-8.jpg\",\"products/womens/women-9.jpg\"]',0,1,1,1,4.70,9,'published','2026-09-07 12:38:10','2026-09-07 13:04:49'),(1,4,3,2,'variable','Noise-Cancelling Wireless Pro Headphones','noise-cancelling-wireless-pro-headphones','ELC-HP-004',NULL,NULL,249.00,199.00,8.00,60,5,5,'in_stock','Studio-quality spatial audio, active hybrid ANC, and up to 40 hours of playtime.','Equipped with custom 40mm beryllium drivers, transparency pass-through mode, four noise-cancelling microphones, and ultra-plush memory foam earcups for prolonged listening comfort.',NULL,'products/electronic/electronic-1.jpg','[\"products/electronic/electronic-2.jpg\",\"products/electronic/electronic-3.jpg\"]',1,1,1,1,4.95,42,'published','2026-09-07 12:38:10','2026-09-07 13:04:49'),(1,5,3,2,'simple','Ultra-Slim Mechanical Wireless Keyboard','ultra-slim-mechanical-wireless-keyboard','ELC-KB-005',NULL,NULL,129.00,115.00,5.00,50,5,5,'in_stock','Compact 75% layout keyboard with hot-swappable switches and RGB backlighting.','Aircraft-grade anodized aluminum body, Bluetooth 5.2 multi-device pairing, low-profile mechanical switches, and long-lasting 4000mAh rechargeable battery.',NULL,'products/electronic/electronic-4.jpg','[\"products/electronic/electronic-5.jpg\",\"products/electronic/electronic-6.jpg\"]',1,0,1,1,4.80,15,'published','2026-09-07 12:38:10','2026-09-07 13:04:49'),(1,6,3,2,'simple','Smart Ambient LED Studio Speaker','smart-ambient-led-studio-speaker','ELC-SP-006',NULL,NULL,159.00,NULL,5.00,35,5,5,'in_stock','360-degree immersive acoustic sound with reactive ambient lighting sync.','Featuring deep bass transducers, Wi-Fi multi-room streaming, voice assistant compatibility, and water-resistant casing for versatile indoor and patio performance.',NULL,'products/electronic/electronic-7.jpg','[\"products/electronic/electronic-8.jpg\",\"products/electronic/electronic-9.jpg\"]',0,1,1,1,4.60,11,'published','2026-09-07 12:38:10','2026-09-07 13:04:49'),(1,7,4,5,'simple','CloudStep Ultra Running Shoes','cloudstep-ultra-running-shoes','SNK-RUN-007',NULL,NULL,135.00,119.00,5.00,75,5,5,'in_stock','Engineered mesh running shoes with responsive nitrogen-infused foam cushioning.','Designed for marathon training and daily walking alike. Offers zero-drop heel support, breathable knit upper, high-traction rubber outsole, and reflective night-running details.',NULL,'products/womens/women-10.jpg','[\"products/womens/women-11.jpg\"]',1,1,1,1,4.90,31,'published','2026-09-07 12:38:10','2026-09-07 13:04:49'),(1,8,5,4,'simple','Botanical Radiance Hydrating Facial Serum','botanical-radiance-hydrating-facial-serum','BTY-SR-008',NULL,NULL,48.00,39.00,5.00,120,5,5,'in_stock','Deeply nourishing serum with hyaluronic acid, vitamin C, and organic botanical extracts.','Restores skin elasticity, locks in 24-hour hydration, and brightens tone with clean, cruelty-free, and vegan certified ingredients.',NULL,'products/womens/women-12.jpg','[\"products/womens/women-13.jpg\"]',1,1,0,1,4.92,53,'published','2026-09-07 12:38:10','2026-09-07 13:04:49'),(1,10,38,6,'variable','OPPO Enco Buds 2 with 28 hours Battery life & Deep Noise Cancellation Bluetooth Headset (Midnight, True Wireless)','oppo-enco-buds-2-with-28-hours-battery-life-deep-noise-cancellation-bluetooth-headset-midnight-true-wireless','OPPO-ENCO-BUDS',NULL,NULL,3999.00,1299.00,0.00,78,5,5,'in_stock','Elevate your audio experience with the OPPO Enco Buds 2, designed for deep bass and crystal-clear sound. Featuring powerful 10mm Large Titanized Drivers, these TWS earbuds deliver a rhythmic, high-fidelity acoustic performance. With AI Deep Noise Cancellation for calls, stay connected without background distractions. Enjoy up to 28 hours of total playback time and take advantage of fast charging???just 10 minutes of charge gives you 1 hour of music. Designed for active lifestyles, these earbuds are IPX4 water-resistant and offer an 80ms ultra-low latency game mode for a lag-free gaming experience. Simple touch controls and instant auto-pairing make them the perfect companion for your smartphone.','',NULL,'products/prod_1788721819_724.png','[\"products\\/prod_gal_1788721819_0_860.jpeg\",\"pr