{\"key\":\"Color\",\"value\":\"Badge\"}]','products/prod_1788722531_690.jpeg','[\"products\\/prod_gal_1788722531_0_228.jpeg\",\"products\\/prod_gal_1788722531_1_793.jpeg\",\"products\\/prod_gal_1788722531_2_451.jpeg\",\"products\\/prod_gal_1788722531_3_833.jpeg\"]',0,1,1,1,4.00,1,'published','2026-10-23 13:10:50','2026-10-23 13:10:50'),(7,86,174,0,'simple','Apple iPhone Duo','apple-iphone-duo','APPLE-IPHONE-T7',NULL,NULL,299900.00,NULL,0.00,104,5,5,'in_stock','iPhone Duo offers the most immersive viewing experience of any iPhone. The aspect ratio of the 19.26 cm (7.6″) Super Retina XDR display4 is consistent across the inner and outer display. The inner display is made of 10 ultra-thin layers with a custom nano‑texture finish that reduces glare. And the under‑display FaceTime camera is hidden until you need it.','','[{\"key\":\"Chip Set\",\"value\":\"A20 Pro chip, 6 Core Processor | Hexa Core\"},{\"key\":\"Rear Camera\",\"value\":\"48MP + 48MP\"},{\"key\":\"Front Camera\",\"value\":\"12MP\"},{\"key\":\"Screen\",\"value\":\"7.6 inch\"}]','products/prod_1789653846_488.jpeg','[\"products\\/prod_gal_1789653846_0_306.jpeg\",\"products\\/prod_gal_1789653846_1_858.jpeg\",\"products\\/prod_gal_1789653846_2_800.jpeg\",\"products\\/prod_gal_1789653846_3_445.jpeg\",\"products\\/prod_gal_1789653847_4_678.jpeg\",\"products\\/prod_gal_1789653847_5_782.jpeg\",\"products\\/prod_gal_1789653847_6_736.jpeg\",\"products\\/prod_gal_1789653847_7_117.jpeg\",\"products\\/prod_gal_1789653847_8_226.jpeg\"]',0,1,1,1,5.00,0,'published','2026-10-23 13:10:50','2026-10-23 13:10:50');
