INSERT INTO `saas_settings` VALUES ('contact_address','123 Commerce Way, Suite 500, New York, NY 10001'),('contact_email','support@ecomsaas.local'),('contact_phone','+1 (800) 123-4567'),('cta_button_text','Explore Plans & Demos'),('currency_code','USD'),('currency_symbol','$'),('hero_badge','🚀 Launch Your Online Store in 60 Seconds'),('hero_heading','Build & Scale Your E-Commerce Brand With Industry-Crafted Templates'),('hero_subheading','Choose from Fashion, Electronics, or Grocery storefronts. Select a flexible plan, connect your domain, and get a complete eCommerce storefront & inventory dashboard instantly.'),('offline_enabled','1'),('offline_instructions','Transfer subscription fee to Account #9012883412 (IFSC: HDFC0001234) and enter your reference ID.'),('payu_enabled','1'),('payu_environment','test'),('payu_merchant_key','n9xHMW'),('payu_merchant_salt','bgCL6ImvxdBt0xlrvHyStQxcgxy4fMAo'),('platform_name','Codeulas Cloud'),('privacy_content','<h3>1. Privacy & Data Isolation Policy</h3><p>We respect your privacy and protect both merchant and customer data using strict server-side tenant isolation, encrypted credentials, and PCI-compliant payment gateways.</p><h3>2. Information We Collect</h3><p>We collect account registration details (name, business name, email, phone, billing address) solely to provision and maintain your SaaS store and process subscription payments.</p><h3>3. Payment Security</h3><p>We never store raw credit card numbers. All payments are processed directly through verified gateways (Stripe, Razorpay, PayU) using cryptographic signature verification.</p>'),('razorpay_enabled','1'),('razorpay_environment','test'),('razorpay_key_id','rzp_test_TcKE5ylmq46eLU'),('razorpay_key_secret','PnmSuJdnQRORebiyEdIxyK4y'),('sandbox_enabled','1'),('site_title','EcomSaaS - Multi-Template E-Commerce Store Platform'),('stripe_enabled','1'),('stripe_environment','test'),('stripe_publishable_key','pk_test_51RVuqmBLpSGcOLX28V0A405OWoPUSR48bMaVIPdgkEqMIUBbDe8fTWurmqWn8UPFI0zQShPiLb2v5eAtops7jTco00V4d8M04U'),('stripe_secret_key','sk_test_51RVuqmBLpSGcOLX2fj0ky4WqRXCb9RTXB2ZLesJtx2Wpt2bC3qkBGONEgAjOEaFs3ulJ5pmzcnjtk5y0DoPs3Waj00WeVX54F4'),('stripe_webhook_secret',''),('terms_content','<h3>1. SaaS Platform Terms of Service</h3><p>Welcome to Codeulas Cloud. By registering a tenant store or subscribing to any plan, you agree to comply with our acceptable use, subscription billing, and data protection policies.</p><h3>2. Subscriptions & Renewals</h3><p>Subscriptions are billed in advance according to the billing interval of your selected plan (Monthly or Yearly). Stores with expired or suspended subscriptions may be placed in read-only or maintenance mode until renewed.</p><h3>3. Tenant Data Ownership</h3><p>Each business owner retains full ownership of their product catalog, customer records, and order history. Strict multi-tenant isolation prevents unauthorized cross-tenant access.</p>');
