INSERT INTO `saas_templates` VALUES (1,'fashion','Fashion Store','Template 1 • Flagship','Modern Apparel, Clothing, Footwear & Lifestyle Storefront','Our signature high-converting Fashion & Lifestyle storefront featuring dynamic lookbook sliders, color/size variant swatches, quick-add cards, product comparisons, and seamless multi-gateway checkout.','[\"Apparel Color Swatches & Size Variations\",\"Interactive Quick View & Product Comparison\",\"Lookbook Hero Sliders & Brand Showcases\",\"Dynamic Filtering by Category, Brand, Color, Size & Price\",\"Customer Wishlist, Saved Cart & Order Tracking\",\"Integrated Stripe, Razorpay, PayU & COD Checkout\"]','website/assets/images/templates/fashion.jpg','website/home?preview_tpl=fashion',1,1,'2026-10-23 10:59:33','2026-10-23 10:59:33'),(2,'electronics','Electronics Store','Template 2 • High-Tech','Gadgets, Smartphones, Laptops, Smartwatches & Audio Storefront','Built for electronics and gadget retailers. Features high-impact widescreen tech sliders, circular department carousels, live flash-deal countdown timers, color-swatch image switching, and spotlight buy boxes.','[\"Live Today\'s Best Deals with Countdown Timer\",\"Interactive Color Variant Swatch Thumbnail Switching\",\"Tech Department Carousel & Coupon Strip\",\"Featured Gadget Spotlight with Direct Buy Box\",\"Technical Specifications & Warranty Badges\",\"Slide-out Mini Cart Drawer with Free Shipping Meter\"]','website/assets/images/templates/electronics.jpg','website/home?preview_tpl=electronics',1,2,'2026-10-23 10:59:33','2026-10-23 10:59:33'),(3,'grocery','Grocery Store','Template 3 • Supermarket','Fresh Produce, Organic Food, Bakery, Dairy & Daily Mart Storefront','Designed for supermarkets, organic grocers, and daily delivery marts. Includes custom SVG grocery department icons, tabbed category product grids, Deal of the Week carousels, pack/weight labels, and 1-click Add to Bag buttons.','[\"SVG Department Icon Bar (Organic, Produce, Meat, Dairy, Bakery)\",\"Instant Category Tab Switching (6-Column Supermarket Grid)\",\"Deal of the Week Carousel with Live Countdown\",\"Unit \\/ Weight \\/ Pack Size Badges on Product Cards\",\"One-Click Direct \\\"Add to Bag\\\" Card Buttons\",\"Live Social-Proof Purchase Notification Toast\"]','website/assets/images/templates/grocery.jpg','website/home?preview_tpl=grocery',1,3,'2026-10-23 10:59:33','2026-10-23 10:59:33');
